'use client'

import { Button } from '@/components/ui/button'
import {
  docsContentPaddingX,
  docsPreviewPrimaryTitleClass,
  docsPreviewSectionPaddingY,
} from '@/lib/docs/docs-container'
import { DOCS_PARTNERS_HOME_HERO } from '@/lib/docs/partners-home-content'
